-- Performance indexes for ERP foreign keys and narrow membership write permissions.
drop policy if exists "market owner manages memberships" on public.cg_market_memberships;
create policy "market owner inserts memberships" on public.cg_market_memberships for insert to authenticated with check (public.cg_market_is_owner(merchant_id) or public.cg_is_admin());
create policy "market owner updates memberships" on public.cg_market_memberships for update to authenticated using (public.cg_market_is_owner(merchant_id) or public.cg_is_admin()) with check (public.cg_market_is_owner(merchant_id) or public.cg_is_admin());
create policy "market owner deletes memberships" on public.cg_market_memberships for delete to authenticated using (public.cg_market_is_owner(merchant_id) or public.cg_is_admin());
